import boto3
from typing import Dict, Any, List

def normalize_expense_fields(document_bytes: bytes) -> Dict[str, Any]:
    client = boto3.client("textract", region_name="us-east-1")

    response = client.analyze_expense(Document={"Bytes": document_bytes})

    if not response.get("ExpenseDocuments"):
        return {}

    doc = response["ExpenseDocuments"][0]
    summary = {f["Type"]["Text"]: f.get("ValueDetection", {}) for f in doc.get("SummaryFields", [])}

    vendor_name = summary.get("VENDOR_NAME", {}).get("Text", "")
    invoice_number = summary.get("INVOICE_RECEIPT_ID", {}).get("Text", "")
    invoice_date = summary.get("INVOICE_RECEIPT_DATE", {}).get("Text", "")

    total_detection = summary.get("INVOICE_TOTAL", {})
    total_amount = total_detection.get("Amount", 0.0)
    currency = total_detection.get("CurrencyCode", summary.get("CURRENCY", {}).get("Text", ""))

    line_items: List[Dict[str, Any]] = []
    for group in doc.get("LineItemGroups", []):
        for item in group.get("LineItems", []):
            item_map = {f["Type"]["Text"]: f.get("ValueDetection", {}) for f in item["LineItemExpenseFields"]}
            line_items.append({
                "description": item_map.get("DESCRIPTION", {}).get("Text", ""),
                "quantity": item_map.get("QUANTITY", {}).get("Amount", 0.0),
                "unit_price": item_map.get("UNIT_PRICE", {}).get("Amount", 0.0),
                "line_total": item_map.get("LINE_ITEM_TOTAL", {}).get("Amount", 0.0)
            })

    return {
        "vendor_name": vendor_name,
        "invoice_number": invoice_number,
        "invoice_date": invoice_date,
        "total_amount": total_amount,
        "currency": currency,
        "line_items": line_items
    }
